mkdir -p /tmp/work && cat > /tmp/work/r.py <<'E'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B='http://localhost:8080'
tok=None
log=set()
def get(path):
    global tok
    while True:
        try:
            if tok is None:
                tok=json.load(urllib.request.urlopen(urllib.request.Request(B+'/token',method='POST')))['token']
            r=urllib.request.Request(B+path,headers={'Authorization':'Bearer '+tok})
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read()[:200]
            if e.code==404: return None
            log.add((e.code,body))
            if e.code==401: tok=None
            ra=e.headers.get('Retry-After')
            time.sleep(float(ra) if ra else 1)
        except Exception as e:
            log.add((str(e),)); time.sleep(1)
orders={};dups=0;p=1
while p:
    d=get(f'/orders?page={p}')
    for o in d['items']:
        if o['id'] in orders:
            dups+=1
            if orders[o['id']]!=o: log.add(('differs',o['id']))
        else: orders[o['id']]=o
    p=int(d['next'].split('=')[-1]) if d['next'] else 0
cust={}
tot=0;cnt=0;reg={'north':0,'south':0,'east':0,'west':0}
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
for o in orders.values():
    if o['status']!='shipped':continue
    t=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
    if t.tzinfo is None: log.add(('naive',o['id']));t=t.replace(tzinfo=timezone.utc)
    if not lo<=t<hi:continue
    c=o['customer_id']
    if c not in cust: cust[c]=get('/customers/'+c)
    if cust[c] is None: log.add(('nocust',c));continue
    v=(o['amount_cents']*(100-cust[c]['discount_pct'])+50)//100
    reg[cust[c]['region']]+=v;tot+=v;cnt+=1
r={'total_cents':tot,'order_count':cnt,'duplicates_skipped':dups,'by_region':reg}
json.dump(r,open('/workspace/result.json','w'),indent=2)
print(r,len(orders),log)
